#!/usr/bin/env bash\nset -e\n\n# Mock rationale: test labeler.sh with various inputs\n\nrun_test() {\n  local expected=$1\n  shift\n  local output\n  output=$(bash ./src/labeler.sh "$@")\n  if [[ "$output" != "$expected" ]]; then\n    echo "FAIL: expected $expected, got $output for args $*"\n    exit 1\n  fi\n  echo "PASS: $expected for $*"\n}\n\nrun_test "python" "app/main.py" "README.md"\nrun_test "docs" "docs/guide.md" "src/util.js"\nrun_test "javascript" "frontend/app.js" "src/module.rb"\nrun_test "misc" "Dockerfile" "Makefile"\n\necho "All tests passed."
